class DragNDropHandler : GTreeDragNDropHandler {
	public static DataFlavor[] supportedFlavors = {
		DataFlavor.stringFlavor,
		DataFlavor.javaFileListFlavor
	};

	/* @Override */
	public void drop(GTreeNode destUserData, Transferable transferable, int dropAction) {
		Msg.info(this, "Dropped the following Files onto " + destUserData);
		try {
			List<object> list = (List<object>) transferable.getTransferData(DataFlavor.javaFileListFlavor);
			foreach (object element in list) {
				Msg.info(this, "\t" + element);
			}
		}
		catch (UnsupportedFlavorException e) {
		}
		catch (IOException e) {
		}
	}

	/* @Override */
	public DataFlavor[] getSupportedDataFlavors(List<GTreeNode> dragUserData) {
		return supportedFlavors;
	}

	/* @Override */
	public int getSupportedDragActions() {
		return DnDConstants.ACTION_COPY;
	}

	/* @Override */
	public object getTransferData(List<GTreeNode> dragUserData, DataFlavor flavor) {
		if (flavor.equals(DataFlavor.javaFileListFlavor)) {
			List<File> fileList = new List<File>();
			foreach (GTreeNode node in dragUserData) {
				FileData fileData = (FileData) node;
				fileList.add(fileData.getFile());
			}
			return fileList;
		}
		else if (flavor.equals(DataFlavor.stringFlavor)) {
			StringBuffer buf = new StringBuffer();
			foreach (GTreeNode element in dragUserData) {
				buf.append(element.toString());
				buf.append("\n");
			}
			return buf.toString();
		}
		return null;

	}

	/* @Override */
	public bool isDropSiteOk(GTreeNode destUserData, DataFlavor[] flavors, int dropAction) {
		if (containsFlavor(flavors, DataFlavor.javaFileListFlavor)) {
			return (destUserData is DirectoryNode);
		}
		return false;
	}

	private bool containsFlavor(DataFlavor[] flavors, DataFlavor flavor) {
		foreach (DataFlavor flavor2 in flavors) {
			if (flavor2.equals(flavor)) {
				return true;
			}
		}
		return false;
	}

	/* @Override */
	public bool isStartDragOk(List<GTreeNode> dragUserData, int dragAction) {
		return true;
	}

